input.command:
node -e '
const {CAUSAL_RE,ATTRIBUTION_RE,OPINION_ERROR,OPINION_WARN,bannedHits,stripQuotes,sentences}=require("./scripts/validate-lib.js");
const j=require("./data/2026-11-09.week.json");
const check=(label,text)=>{
 for(const s of sentences(stripQuotes(text))){
  if(CAUSAL_RE.test(s)&&!ATTRIBUTION_RE.test(s))console.log("CAUSAL ["+label+"] "+s.slice(0,180));
 }
 for(const w of bannedHits(stripQuotes(text),OPINION_ERROR))console.log("OPINION-ERR ["+label+"] "+w);
 for(const w of bannedHits(stripQuotes(text),OPINION_WARN))console.log("HEDGE ["+label+"] "+w);
};
j.summary.forEach((p,i)=>check("summary "+i,p));
j.happened.forEach(h=>{check("happened "+h.id+" headline",h.headline);h.bullets.forEach((b,i)=>check("happened "+h.id+" b"+i,b));});
j.connects.forEach(c=>{check("connect "+c.id+" title",c.title);c.explanation.forEach((p,i)=>check("connect "+c.id+" p"+i,p));});
j.unknowns.forEach(u=>["evidence_ends","disagreement","would_confirm","would_invalidate"].forEach(k=>u[k]&&check("unknown "+u.id+" "+k,u[k])));
console.log("--- scan done ---");
'

